<script setup>
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import InputError from '@/Components/InputError.vue';
import { Head, Link, useForm } from '@inertiajs/vue3';
import { ref } from 'vue';
defineProps({enquiries:Object});
const selected=ref(null), form=useForm({status:'new'}), deletion=useForm({});
function open(item){selected.value=item;form.status=item.status;form.clearErrors();}
function save(){form.put(route('backend.training-enquiries.update',selected.value.id),{preserveScroll:true,onSuccess:()=>selected.value=null});}
function remove(item){if(confirm('Delete this training enquiry?'))deletion.delete(route('backend.training-enquiries.destroy',item.id),{preserveScroll:true,onSuccess:()=>selected.value=null});}
</script>
<template><AuthenticatedLayout><Head title="Training Enquiries" /><div class="p-4 md:p-8 space-y-6"><h1 class="text-xl font-semibold">Training Enquiries</h1><Link :href="route('backend.programs.index')" class="text-indigo-600">Manage programs</Link>
<form v-if="selected" @submit.prevent="save" class="bg-white rounded-2xl p-6 space-y-4"><h2 class="font-semibold">{{selected.full_name}} — {{selected.organisation}}</h2><dl class="grid md:grid-cols-2 gap-4"><div v-for="(label,key) in {email:'Email',phone:'Phone',programme_label:'Requested program',participants:'Participants',delivery_preference:'Delivery preference',notes:'Notes',source_page:'Source page',created_at:'Received'}" :key="key"><dt class="font-medium">{{label}}</dt><dd class="whitespace-pre-wrap break-words">{{selected[key]||'—'}}</dd></div></dl><label class="block">Status<select v-model="form.status" class="ml-3 rounded-lg border-gray-200"><option v-for="status in ['new','contacted','quoted','closed']" :key="status">{{status}}</option></select></label><InputError :message="form.errors.status" /><div class="flex gap-4"><button :disabled="form.processing" class="bg-indigo-600 text-white px-4 py-2 rounded-lg">Save status</button><button type="button" @click="selected=null">Close</button></div></form>
<section class="bg-white rounded-2xl p-6"><div class="overflow-x-auto"><table class="w-full text-sm text-left"><thead><tr><th class="p-3">Name</th><th class="p-3">Program</th><th class="p-3">Status</th><th class="p-3">Actions</th></tr></thead><tbody><tr v-for="item in enquiries.data" :key="item.id" class="border-t"><td class="p-3">{{item.full_name}}<div class="text-gray-500">{{item.organisation}}</div></td><td class="p-3">{{item.programme_label||item.programme?.title||'General enquiry'}}</td><td class="p-3">{{item.status}}</td><td class="p-3"><div class="flex gap-4"><button @click="open(item)" class="text-indigo-600">View / Update</button><button :disabled="deletion.processing" @click="remove(item)" class="text-red-600">Delete</button></div></td></tr><tr v-if="!enquiries.data.length"><td colspan="4" class="p-6 text-gray-500">No training enquiries yet.</td></tr></tbody></table></div><nav class="flex gap-4 mt-4"><Link v-if="enquiries.prev_page_url" :href="enquiries.prev_page_url">Previous</Link><span>Page {{enquiries.current_page}} of {{enquiries.last_page}}</span><Link v-if="enquiries.next_page_url" :href="enquiries.next_page_url">Next</Link></nav></section></div></AuthenticatedLayout></template>
